CREATE TABLE pto_types (id BIGSERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL,accrual_rate_per_period NUMERIC(10,4) NOT NULL,max_carryover NUMERIC(10,2) NOT NULL,paid BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uk_pto_type_name UNIQUE(name));
CREATE TABLE pto_requests (id BIGSERIAL PRIMARY KEY,employee_id BIGINT NOT NULL,pto_type_id BIGINT NOT NULL REFERENCES pto_types(id),start_date DATE NOT NULL,end_date DATE NOT NULL,hours NUMERIC(10,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',reviewed_by UUID,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_pto_request_employee_dates ON pto_requests(employee_id,start_date,end_date); CREATE INDEX idx_pto_request_status ON pto_requests(status);
CREATE TABLE pto_balances (id BIGSERIAL PRIMARY KEY,employee_id BIGINT NOT NULL,pto_type_id BIGINT NOT NULL REFERENCES pto_types(id),accrued_hours NUMERIC(10,2) NOT NULL DEFAULT 0,used_hours NUMERIC(10,2) NOT NULL DEFAULT 0,reserved_hours NUMERIC(10,2) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uk_pto_balance_employee_type UNIQUE(employee_id,pto_type_id));
CREATE TABLE pto_ledger_entries (id BIGSERIAL PRIMARY KEY,employee_id BIGINT NOT NULL,pto_type_id BIGINT NOT NULL REFERENCES pto_types(id),hours_delta NUMERIC(10,2) NOT NULL,entry_type VARCHAR(20) NOT NULL,source_request_id BIGINT REFERENCES pto_requests(id),occurred_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_pto_ledger_employee_type_time ON pto_ledger_entries(employee_id,pto_type_id,occurred_at);
